target.css:
:root {
  --ink: #243248;
  --muted: #718096;
  --paper: #fffdf8;
  --navy: #294a66;
  --aqua: #d8f0e9;
  --mint: #79c6ae;
  --coral: #ef806d;
  --cream: #f8eed5;
  --line: #dce4e5;
  --white: #ffffff;
}

.bento-board,
.bento-board * {
  box-sizing: border-box;
}

.bento-board {
  width: 500px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.bento-board h1,
.bento-board h2,
.bento-board p,
.bento-board ul {
  margin: 0;
}

.board-header {
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  font-size: 21px;
  background: var(--cream);
  border-radius: 12px;
}

.brand h1 {
  font-size: 18px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -0.3px;
}

.brand p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1;
}

.status {
  padding: 5px 8px;
  color: var(--navy);
  background: var(--aqua);
  border-radius: 999px;
  font-size: 10px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.progress {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  padding: 3px;
  background: var(--line);
  border-radius: 9px;
}

.progress span {
  padding: 5px 7px;
  color: var(--muted);
  text-align: center;
  font-size: 11px;
  line-height: 1;
  font-weight: 700;
  border-radius: 6px;
}

.progress .active {
  color: var(--navy);
  background: var(--white);
}

.assembly-grid {
  height: 139px;
  display: grid;
  grid-template-columns: 1.18fr 0.78fr 1fr;
  gap: 8px;
}

.recipe-card,
.timing-card,
.checklist-card {
  border: 1px solid var(--line);
}

.recipe-card {
  padding: 10px;
  background: var(--white);
  border-radius: 12px;
}

.card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

.bento-board h2 {
  font-size: 13px;
  line-height: 1.1;
  font-weight: 800;
}

.tag {
  padding: 3px 5px;
  color: var(--coral);
  background: var(--cream);
  border-radius: 4px;
  font-size: 9px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.ingredient-list,
.checks {
  padding: 0;
  list-style: none;
}

.ingredient-list li {
  display: flex;
  justify-content: space-between;
  padding: 7px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.1;
}

.ingredient-list strong {
  color: var(--ink);
  font-weight: 800;
}

.timing-card {
  padding: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--navy);
  border-color: var(--navy);
  border-radius: 12px;
}

.timing-card h2,
.timing-card p {
  color: var(--white);
}

.timer {
  margin-top: 10px !important;
  font-size: 25px;
  line-height: 0.95;
  font-weight: 800;
  letter-spacing: -1px;
}

.timing-card p:not(.timer) {
  margin-top: 4px;
  color: var(--aqua);
  font-size: 10px;
}

button {
  border: 0;
  cursor: pointer;
  font-weight: 800;
}

.pause {
  width: 100%;
  margin-top: auto;
  padding: 6px;
  color: var(--navy);
  background: var(--aqua);
  border-radius: 7px;
  font-size: 10px;
  line-height: 1;
}

.checklist-card {
  padding: 10px;
  background: var(--aqua);
  border-color: var(--mint);
  border-radius: 12px 12px 18px 12px;
}

.checklist-card h2 {
  display: flex;
  justify-content: space-between;
}

.checklist-card h2 span {
  color: var(--navy);
  font-size: 10px;
}

.checks {
  margin-top: 7px !important;
}

.checks li {
  padding: 4px 0;
  color: var(--navy);
  font-size: 11px;
  line-height: 1.1;
  border-top: 1px solid var(--mint);
}

.checks li::before {
  content: "○";
  display: inline-block;
  width: 16px;
  color: var(--muted);
  font-weight: 800;
}

.checks li.done::before {
  content: "✓";
  color: var(--coral);
}

.board-footer {
  min-height: 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 2px;
}

.board-footer p {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.1;
}

.board-footer p span {
  color: var(--coral);
  font-size: 12px;
}

.primary {
  padding: 7px 10px;
  color: var(--white);
  background: var(--coral);
  border-radius: 8px;
  font-size: 10px;
  line-height: 1;
}

